-- SAIF v0.26A.1.12 Parked Vehicle Canonical Planner import
-- SAFETY: planner tables only; parked_vehicles runtime untouched.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
SET @offline_session_key := _utf8mb4'ecbbfa867b491c93570b92e0c6d3ff34e1e916da9df914d83edb066c1eac52c3' COLLATE utf8mb4_unicode_ci;
SET @offline_session_id := (SELECT id FROM offline_import_sessions WHERE session_key COLLATE utf8mb4_unicode_ci=@offline_session_key LIMIT 1);
DELETE p FROM offline_vehicle_apply_plan p WHERE p.session_id=@offline_session_id AND p.planner_version='saif-vehicle-canonical-planner-v0.26A.1.12';
DELETE b FROM offline_vehicle_apply_batches b WHERE b.session_id=@offline_session_id AND b.planner_version='saif-vehicle-canonical-planner-v0.26A.1.12';
COMMIT;
SELECT decision_code,COUNT(*) AS rows_count,SUM(recommended_enabled=1) AS recommended_enabled,SUM(enabled=1) AS enabled_should_be_zero,SUM(apply_status<>'draft') AS nondraft_should_be_zero FROM offline_vehicle_apply_plan WHERE session_id=@offline_session_id AND planner_version='saif-vehicle-canonical-planner-v0.26A.1.12' GROUP BY decision_code ORDER BY decision_code;
